/**
 * SOC - Wazuh Alert Normalization
 * Stage: Normalize (#67)
 * Version: 1.2
 *
 * Supported input formats:
 * - Raw Wazuh alert
 * - Elasticsearch document (_source)
 * - Shuffle wrapper (all_fields)
 *
 * Output:
 * - Unified alert metadata
 * - Typed observables
 * - Primary observable
 * - Deduplication key
 *
 * n8n Code node:
 * Mode: Run Once for All Items
 */

// ============================================================
// 1. INPUT
// ============================================================

const items = $input.all();

// ============================================================
// 2. HELPERS
// ============================================================

function get(obj, path) {
  return path.split('.').reduce(
    (value, key) => value == null ? undefined : value[key],
    obj
  );
}

function normalizePath(value) {
  return typeof value === 'string'
    ? value.replace(/\\\\/g, '\\')
    : value;
}

// IPv4 validation
function isIPv4(value) {
  if (typeof value !== 'string') return false;

  const parts = value.split('.');

  return parts.length === 4 && parts.every(part =>
    /^\d{1,3}$/.test(part) &&
    Number(part) >= 0 &&
    Number(part) <= 255
  );
}

// IPv6 validation, including compressed and IPv4-mapped forms
function isIPv6(value) {
  if (typeof value !== 'string' || !value.includes(':')) {
    return false;
  }

  let ip = value.toLowerCase();

  // Zone identifiers are not handled
  if (ip.includes('%')) return false;

  // Convert an embedded IPv4 tail into two IPv6 groups
  if (ip.includes('.')) {
    const lastColon = ip.lastIndexOf(':');

    if (lastColon === -1 ||
        !isIPv4(ip.slice(lastColon + 1))) {
      return false;
    }

    ip = ip.slice(0, lastColon) + ':0:0';
  }

  const doubleColon = ip.indexOf('::');

  if (doubleColon !== -1) {
    // Only one :: is allowed
    if (ip.indexOf('::', doubleColon + 2) !== -1) {
      return false;
    }

    const parts = ip.split('::');

    const left = parts[0]
      ? parts[0].split(':')
      : [];

    const right = parts[1]
      ? parts[1].split(':')
      : [];

    const groups = [...left, ...right];

    if (!groups.every(group => /^[0-9a-f]{1,4}$/i.test(group))) {
      return false;
    }

    // :: must replace at least one group
    return groups.length < 8;
  }

  const groups = ip.split(':');

  return groups.length === 8 &&
    groups.every(group => /^[0-9a-f]{1,4}$/i.test(group));
}

function isIP(value) {
  return isIPv4(value) || isIPv6(value);
}

// Private, loopback and link-local IP detection
function isPrivateIP(ip) {
  if (isIPv4(ip)) {
    const p = ip.split('.').map(Number);

    return p[0] === 10 ||
      p[0] === 127 ||
      (p[0] === 172 && p[1] >= 16 && p[1] <= 31) ||
      (p[0] === 192 && p[1] === 168) ||
      (p[0] === 169 && p[1] === 254);
  }

  if (isIPv6(ip)) {
    const value = ip.toLowerCase();

    return value === '::' ||
      value === '::1' ||
      /^f[cd]/i.test(value) ||
      /^fe[89ab]/i.test(value);
  }

  return false;
}

// Domain validation
function isDomain(value) {
  if (typeof value !== 'string') return false;

  const domain = value.toLowerCase().replace(/\.$/, '');

  if (domain.length > 253 || domain.includes('://')) {
    return false;
  }

  if (isIP(domain)) return false;

  return /^(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/i.test(domain);
}

// Hash validation
function isValidHash(value) {
  return typeof value === 'string' &&
    (
      /^[a-f0-9]{32}$/i.test(value) ||
      /^[a-f0-9]{40}$/i.test(value) ||
      /^[a-f0-9]{64}$/i.test(value)
    );
}

// Windows Registry detection
function isRegistryPath(value) {
  return typeof value === 'string' &&
    /^(HKEY_|HKLM\\|HKCU\\|HKCR\\|HKU\\|HKCC\\)/i.test(value);
}

// ============================================================
// 3. NORMALIZATION
// ============================================================

function normalizeAlert(root) {

  const body = root.body ?? root;

  // Detect input format
  const alert =
    body._source ??
    body.all_fields ??
    body;

  if (!alert.rule || alert.rule.id === undefined) {
    throw new Error(
      'Invalid Wazuh alert: missing rule.id'
    );
  }

  const observables = [];
  const seen = new Set();

  // ----------------------------------------------------------
  // Add observable with deduplication
  // ----------------------------------------------------------

  function add(dataType, value, field, extra = {}) {
    if (value === undefined || value === null) return;

    const data = String(value).trim();

    if (!data || data === '-' || data === '(null)') {
      return;
    }

    const key = `${dataType}|${data.toLowerCase()}`;

    if (seen.has(key)) return;

    seen.add(key);

    observables.push({
      dataType,
      data,
      field,
      internal: false,
      ...extra
    });
  }

  // ==========================================================
  // 4. IP ADDRESSES
  // ==========================================================

  const ipFields = [
    'data.srcip',
    'data.src_ip',
    'data.dstip',
    'data.dest_ip',
    'data.win.eventdata.sourceIp',
    'data.win.eventdata.destinationIp',
    'data.win.eventdata.ipAddress',
    'agent.ip'
  ];

  for (const field of ipFields) {
    const value = get(alert, field);

    if (typeof value === 'string' && isIP(value)) {
      add('ip', value, field, {
        internal: isPrivateIP(value)
      });
    }
  }

  // ==========================================================
  // 5. DOMAINS
  // ==========================================================

  const domainFields = [
    'data.domain',
    'data.win.eventdata.queryName',
    'data.dns.rrname',
    'data.http.hostname',
    'data.tls.sni'
  ];

  for (const field of domainFields) {
    const value = get(alert, field);

    if (typeof value === 'string' && isDomain(value)) {
      const domain = value.toLowerCase().replace(/\.$/, '');

      add('domain', domain, field, {
        internal: /\.(lab|local|lan|internal|localdomain)$/.test(domain)
      });
    }
  }

  // ==========================================================
  // 6. URLS
  // ==========================================================

  const httpHost = get(alert, 'data.http.hostname');

  for (const field of [
    'data.url',
    'data.http.url'
  ]) {
    const value = get(alert, field);

    if (typeof value !== 'string' || !value.trim()) {
      continue;
    }

    if (/^https?:\/\//i.test(value)) {
      add('url', value, field);

      try {
        const hostname = new URL(value)
          .hostname
          .toLowerCase()
          .replace(/\.$/, '');

        if (isDomain(hostname)) {
          add('domain', hostname, `${field}#hostname`, {
            internal: /\.(lab|local|lan|internal|localdomain)$/.test(hostname)
          });
        }
      } catch {
        // Keep the URL observable if hostname parsing fails.
      }

    } else if (
      field === 'data.http.url' &&
      typeof httpHost === 'string'
    ) {
      add(
        'url',
        `http://${httpHost}${value.startsWith('/') ? '' : '/'}${value}`,
        field
      );

    } else {
      add('uri_path', value, field);
    }
  }

  // ==========================================================
  // 7. HASHES
  // ==========================================================

  const hashes = get(alert, 'data.win.eventdata.hashes');

  if (typeof hashes === 'string') {
    for (const part of hashes.split(',')) {
      const separator = part.indexOf('=');

      if (separator === -1) continue;

      const algorithm = part
        .slice(0, separator)
        .trim()
        .toUpperCase();

      const value = part
        .slice(separator + 1)
        .trim()
        .toLowerCase();

      const lengths = {
        MD5: 32,
        SHA1: 40,
        SHA256: 64
      };

      if (
        lengths[algorithm] === value.length &&
        isValidHash(value)
      ) {
        add(
          'hash',
          value,
          'data.win.eventdata.hashes',
          { algorithm }
        );
      }
    }
  }

  // Syscheck hashes
  for (const [field, algorithm] of [
    ['syscheck.sha256_after', 'SHA256'],
    ['syscheck.sha1_after', 'SHA1'],
    ['syscheck.md5_after', 'MD5'],
    ['syscheck.sha256_before', 'SHA256'],
    ['syscheck.sha1_before', 'SHA1'],
    ['syscheck.md5_before', 'MD5']
  ]) {
    const value = get(alert, field);

    if (
      typeof value === 'string' &&
      isValidHash(value)
    ) {
      add('hash', value.toLowerCase(), field, {
        algorithm
      });
    }
  }

  // ==========================================================
  // 8. FILENAMES AND FILE PATHS
  // ==========================================================

  for (const field of [
    'data.win.eventdata.image',
    'data.win.eventdata.targetFilename',
    'syscheck.path'
  ]) {
    const value = normalizePath(get(alert, field));

    if (typeof value !== 'string' || !value.trim()) {
      continue;
    }

    // Registry paths are handled separately
    if (isRegistryPath(value)) continue;

    const filename = value.split(/[\\/]/).pop();

    // Accept filenames with and without extensions
    if (filename) {
      add('filename', filename, field, {
        path: value
      });
    }
  }

  // ==========================================================
  // 9. WINDOWS REGISTRY
  // ==========================================================

  const registryPath = normalizePath(
    get(alert, 'syscheck.path')
  );

  if (isRegistryPath(registryPath)) {
    add(
      'registry_key',
      registryPath,
      'syscheck.path',
      { internal: true }
    );
  }

  // ==========================================================
  // 10. USER ACCOUNTS
  // ==========================================================

  const userFields = [
    'data.win.eventdata.user',
    'data.win.eventdata.targetUserName',
    'data.srcuser',
    'data.dstuser',
    'syscheck.uname_after'
  ];

  for (const field of userFields) {
    const value = normalizePath(get(alert, field));

    if (typeof value === 'string') {
      add('other', value, field, {
        kind: 'user',
        internal: true
      });
    }
  }

  // ==========================================================
  // 11. USER-AGENT
  // ==========================================================

  const userAgentFields = [
    'data.http.http_user_agent',
    'data.http.user_agent'
  ];

  for (const field of userAgentFields) {
    const value = get(alert, field);

    if (typeof value === 'string') {
      add('user-agent', value, field);
    }
  }

  // ==========================================================
  // 12. HOSTNAME
  // ==========================================================

  if (alert.agent?.name) {
    add(
      'hostname',
      alert.agent.name,
      'agent.name',
      { internal: true }
    );
  }

  // ==========================================================
  // 13. PRIMARY OBSERVABLE
  // ==========================================================

  const pick = predicate =>
    observables.find(predicate)?.data;

  const primary =
    pick(o => o.dataType === 'ip' && !o.internal) ??
    pick(o => o.dataType === 'hash') ??
    pick(o => o.dataType === 'domain' && !o.internal) ??
    pick(o => o.dataType === 'filename') ??
    pick(o => o.dataType === 'registry_key') ??
    pick(o => o.dataType === 'uri_path') ??
    '-';

  // ==========================================================
  // 14. DEDUPLICATION KEY
  // ==========================================================

  const WEB_GROUPS = ['web', 'accesslog', 'web_scan'];

  const ruleId = String(alert.rule.id);

  const agentId = String(
    alert.agent?.id ?? 'na'
  );

  const signatureId =
    get(alert, 'data.alert.signature_id') ?? '';

  // Source IP: private addresses are kept on purpose,
  // only source-like fields are used (not dstip, not agent.ip)
  let srcIp = '';

  for (const field of [
    'data.srcip',
    'data.src_ip',
    'data.win.eventdata.sourceIp',
    'data.win.eventdata.ipAddress'
  ]) {
    const value = get(alert, field);

    if (typeof value === 'string' && isIP(value.trim())) {
      srcIp = value.trim().toLowerCase();
      break;
    }
  }

  // Web rules: key = rule + agent + source IP (path is ignored).
  // Only when a source IP exists, otherwise fall back to the default key.
  const isWebRule = (alert.rule.groups ?? [])
    .some(group => WEB_GROUPS.includes(group));

  const webMode = isWebRule && srcIp !== '';

  const dedupKey = [
    'soc:dedup',
    ruleId,
    signatureId,
    agentId,
    srcIp || '-',
    webMode ? '*' : primary
  ].join(':').slice(0, 300);

  // ==========================================================
  // 15. NORMALIZED OUTPUT
  // ==========================================================

  const mitre = alert.rule.mitre ?? {};

  const sourceFormat =
    body._source || root._source
      ? 'elasticsearch'
      : body.all_fields
        ? 'shuffle-wrapper'
        : 'raw';

  return {
    alert_id:
      alert.id ??
      body._id ??
      root._id ??
      null,

    timestamp: alert.timestamp ?? null,

    manager: alert.manager?.name ?? 'wazuh',

    source_format: sourceFormat,

    rule: {
      id: ruleId,
      level: Number(alert.rule.level ?? 0),
      description: alert.rule.description ?? '',
      groups: alert.rule.groups ?? [],
      mitre_ids: mitre.id ?? [],
      mitre_tactics: mitre.tactic ?? [],
      mitre_techniques: mitre.technique ?? [],
      firedtimes: alert.rule.firedtimes ?? null
    },

    agent: {
      id: agentId,
      name: alert.agent?.name ?? 'unknown',
      ip: alert.agent?.ip ?? null
    },

    location: alert.location ?? null,

    decoder: alert.decoder?.name ?? null,

    syscheck: alert.syscheck ?? null,

    signature: get(alert, 'data.alert.signature') ?? null,

    command_line: normalizePath(
      get(alert, 'data.win.eventdata.commandLine')
    ) ?? null,

    full_log:
      typeof alert.full_log === 'string'
        ? alert.full_log.slice(0, 2000)
        : null,

    observables,

    primary_observable: primary,

    dedup_key: dedupKey,
    source_ip: srcIp || null,

    dedup_mode: webMode ? 'web-source' : 'default'
  };
}


// ============================================================
// 16. PROCESS ALL INPUT ITEMS
// ============================================================

return items.map(item => ({
  json: normalizeAlert(item.json)
}));

const rows = $input.all().map(item => item.json ?? {});
const errorRows = rows.filter(item => item.service && item.error !== undefined);

let alert = {};
try {
  alert = $('Normalize Alert').first().json ?? {};
} catch {}

function clean(obj) {
  return Object.fromEntries(
    Object.entries(obj).filter(([, value]) =>
      value !== undefined &&
      value !== null &&
      value !== '' &&
      !(Array.isArray(value) && value.length === 0)
    )
  );
}

function compactObservable(item) {
  if (typeof item === 'string') {
    return { value: item };
  }

  return clean({
    type: item.type ?? item.dataType ?? item.kind,
    value: item.data ?? item.value ?? item.observable ?? item.ioc,
    field: item.field ?? item.source_field ?? item.key,
    internal: item.internal ?? item.is_internal,
    cortex_eligible: item.cortex_eligible,
  });
}

function getTagNames(...tagLists) {
  const names = [];
  const seen = new Set();

  for (const tagList of tagLists) {
    const entries = Array.isArray(tagList)
      ? tagList
      : tagList === undefined || tagList === null
        ? []
        : [tagList];

    for (const tag of entries) {
      const name = typeof tag === 'string'
        ? tag
        : tag?.name;

      if (typeof name !== 'string' || name.trim() === '') {
        continue;
      }

      const trimmedName = name.trim();
      const key = trimmedName.toLowerCase();

      if (!seen.has(key)) {
        seen.add(key);
        names.push(trimmedName);
      }
    }
  }

  return names;
}

const rawObservables = Array.isArray(alert.observables)
  ? alert.observables
  : [];

const observables = rawObservables.map(compactObservable);

const isAnalyzerRow = item =>
  Boolean(
    item.workerName ||
    item.workerDefinitionId ||
    item.analyzerName
  );

function isMispAttribute(item) {
  return item.value !== undefined && (item.Event != null || item.event_id != null);
}

const mispRows = rows.filter(isMispAttribute);

const cortexRows = rows.filter(isAnalyzerRow);

const skippedIpRows = rows.filter(item => {
  if (item.record_type === 'cortex_skipped') {
    return true;
  }

  if (isMispAttribute(item) || isAnalyzerRow(item)) {
    return false;
  }

  const type = String(
    item.data_type ?? item.dataType ?? item.type ?? ''
  ).toLowerCase();

  const value =
    item.observable ??
    item.value ??
    item.data;

  return type.includes('ip') && value !== undefined && value !== null;
});

// Deduplicate repeated MISP references by attribute UUID, then ID.
// If neither exists, use event ID + attribute type + value.
const uniqueMispRowsByKey = new Map();
// Some copies of the same attribute contain only the numeric ID.
// Resolve those even when the row carrying both identifiers arrives later.
const uuidById = new Map();
for (const item of mispRows) {
  const id = String(item.id ?? '').trim();
  const uuid = String(item.uuid ?? '').trim().toLowerCase();
  if (id && uuid) uuidById.set(id, uuid);
}

for (const item of mispRows) {
  const attributeId = String(item.id ?? '').trim();
  const uuid = String(item.uuid ?? '').trim().toLowerCase() || uuidById.get(attributeId);
  const eventId = String(item.Event?.id ?? item.event_id ?? '').trim();
  const type = String(item.type ?? 'unknown').trim();
  const value = String(item.value ?? '').trim();

  let attributeKey;
  if (uuid) attributeKey = `uuid:${uuid}`;
  else if (attributeId) attributeKey = `id:${attributeId}`;
  else if (eventId) attributeKey = `fallback:${eventId}\u0000${type.toLowerCase()}\u0000${value}`;
  else attributeKey = Symbol(); // Missing identity and event: preserve this row.

  const tags = getTagNames(
    item.Tag,
    item.Event?.Tag,
    item.Event?.Tags
  );

  const existing = uniqueMispRowsByKey.get(attributeKey);

  if (existing) {
    existing.tags = getTagNames(existing.tags, tags);
    if (!existing.id && attributeId) existing.id = item.id;
    if (existing.item.to_ids == null && item.to_ids != null) {
      existing.item = { ...existing.item, to_ids: item.to_ids };
    }
  } else {
    uniqueMispRowsByKey.set(attributeKey, {
      item,
      tags,
      id: item.id,
      uuid,
    });
  }
}

const uniqueMispRows = [...uniqueMispRowsByKey.values()];
const groupedMisp = new Map();

for (const { item, tags, id, uuid } of uniqueMispRows) {
  const type = item.type ?? 'unknown';
  const value = item.value ?? '';
  const key = `${type}\u0000${value}`;

  if (!groupedMisp.has(key)) {
    groupedMisp.set(key, {
      type,
      value,
      attributes: [],
    });
  }

  const threatLevel = item.Event?.ThreatLevel;

  groupedMisp.get(key).attributes.push(clean({
    uuid,
    id,
    comment: item.comment,
    to_ids: item.to_ids,
    disable_correlation: item.disable_correlation,
    event: clean({
      id: item.Event?.id ?? item.event_id,
      title: item.Event?.info,
      date: item.Event?.date,
      threat_level:
        typeof threatLevel === 'object'
          ? threatLevel?.name
          : threatLevel,
    }),
    tags,
  }));
}

function getCortexSummary(item) {
  const report = item.report;

  if (!report || typeof report !== 'object') {
    return undefined;
  }

  const full = report.full ?? {};

  const analyzer = String(
    item.workerName ??
    item.workerDefinitionId ??
    item.analyzerName ??
    ''
  ).toLowerCase();

  if (analyzer.includes('abuseipdb')) {
    const result = full.values?.[0] ?? {};
    const data = result.data ?? result;
    const categories =
      result.category_counts ??
      full.category_counts ??
      [];
    const freshness =
      result.freshness ??
      full.freshness ??
      {};

    return clean({
      whitelisted: data.isWhitelisted,
      abuse_confidence_score: data.abuseConfidenceScore,
      usage: data.usageType,
      country: data.countryName,
      country_code: data.countryCode,
      isp: data.isp,
      total_reports: data.totalReports,
      last_reported_at: data.lastReportedAt,
      reports_last_24h: freshness.last24h,
      reports_last_7d: freshness.last7d,
      top_categories: categories
        .slice()
        .sort((a, b) => (b.count ?? 0) - (a.count ?? 0))
        .slice(0, 3)
        .map(category => clean({
          name: category.category,
          count: category.count,
        })),
    });
  }

  if (analyzer.includes('maxmind')) {
    const country =
      full.country ??
      full.registered_country ??
      {};

    const continent = full.continent ?? {};

    return clean({
      country: country.name,
      country_code: country.iso_code,
      continent: continent.name,
      ip: full.traits?.ip_address,
    });
  }

  if (analyzer.includes('maltiverse')) {
    const blacklist = Array.isArray(full.blacklist)
      ? full.blacklist
      : [];

    const keywords =
      /malicious|compromis|malware|phish|botnet|ransomware|cobalt.?strike|rat|backdoor|trojan|infostealer|exploit|gamarue|mirai|emotet|adware|banker|virut|scam|fraud/i;

    const historicalMatches = blacklist.filter(entry => {
      const labels = Array.isArray(entry.labels)
        ? entry.labels
        : [];

      const benign = labels.some(label =>
        String(label).toLowerCase() === 'benign'
      );

      const threatLabel = labels.some(label =>
        /malicious|compromised|malware/i.test(String(label))
      );

      const threatDescription = keywords.test(
        String(entry.description ?? '')
      );

      return !benign && (threatLabel || threatDescription);
    });

    const examples = historicalMatches
      .slice()
      .sort((a, b) =>
        (Date.parse(b.last_seen ?? '') || 0) -
        (Date.parse(a.last_seen ?? '') || 0)
      )
      .slice(0, 3)
      .map(entry => clean({
        description: entry.description,
        source: entry.source,
        last_seen: entry.last_seen,
      }));

    return clean({
      classification: full.classification,
      country_code: full.asn_country_code ?? full.country_code,
      asn_cidr: full.asn_cidr,
      historical_matches: {
        count: historicalMatches.length,
        examples,
      },
    });
  }

  const taxonomies = (report.summary?.taxonomies ?? []).map(taxonomy =>
    clean({
      level: taxonomy.level,
      namespace: taxonomy.namespace,
      predicate: taxonomy.predicate,
      value:
        typeof taxonomy.value === 'string' &&
        taxonomy.value.toLowerCase() === 'unkown'
          ? 'unknown'
          : taxonomy.value,
    })
  );

  let message = full.message ?? full.status;

  if (
    typeof message === 'string' &&
    /^no record found for /i.test(message)
  ) {
    message = 'No record found';
  }

  return clean({
    taxonomies,
    message,
  });
}

const cortexResults = cortexRows.map(item => {
  const rawStatus = String(item.status ?? '').toLowerCase();
  const report = item.report;

  let status = rawStatus || 'unknown';

  if (status === 'success') {
    status = 'complete';
  }

  if (['waiting', 'inprogress', 'running'].includes(status)) {
    status = 'pending';
  }

  if (['failure', 'failed', 'error'].includes(status)) {
    status = 'failed';
  }

  if (report && typeof report === 'object' && report.success === false) {
    status = 'failed';
  }

  const summary = getCortexSummary(item);

  return clean({
    analyzer:
      item.workerName ??
      item.workerDefinitionId ??
      item.analyzerName,
    observable: item.data,
    data_type: item.dataType,
    status,
    summary:
      summary && Object.keys(summary).length > 0
        ? summary
        : undefined,
  });
});

