      observable: result.observable,
      status: result.status,
    })),
  ...errorRows.map(item => ({
    service: item.service,
    node: item.node,
    observable: item.observable,
    error: item.error,
  })),
];

const rule = alert.rule ?? {};
const agent = alert.agent ?? {};
const syscheck = alert.syscheck ?? {};

return [{
  json: {
    alert: clean({
      id: alert.alert_id ?? alert.id,
      timestamp: alert.timestamp,
      manager: alert.manager,
      source_format: alert.source_format,
      tlp: alert.tlp,
      rule: clean({
        id: rule.id,
        level: rule.level,
        description: rule.description,
      }),
      agent: clean({
        id: agent.id,
        name: agent.name,
        ip: agent.ip,
      }),
      groups: alert.groups,
      mitre: clean({
        ids: alert.mitre_ids,
        tactics: alert.mitre_tactics,
        techniques: alert.mitre_techniques,
      }),
      syscheck: clean({
        path: syscheck.path,
        event: syscheck.event,
        sha256_before: syscheck.sha256_before,
