      results: cortexResults,
      skipped_by_filter: skippedByFilter,
    },

    processing: {
      status: pending.length > 0
        ? 'partial'
        : failed.length > 0
          ? 'complete_with_errors'
          : 'complete',
      pending,
      failed,
    },
  },
}];

const items = $input.all();
const seen = new Map();
const output = [];

function isInternal(value) {
  return value === true || String(value ?? '').toLowerCase() === 'true';
}

for (const item of items) {
  const observable = item.json ?? {};

  const nested =
    observable.observables &&
    typeof observable.observables === 'object' &&
    !Array.isArray(observable.observables)
      ? observable.observables
      : {};

  const type = String(
    observable.type ?? nested.type ?? nested.dataType ?? ''
  ).trim().toLowerCase();

  let value = String(
    observable.value ?? nested.value ?? nested.data ?? ''
  ).trim();

  const field = observable.field ?? nested.field;
  const internal = isInternal(observable.internal ?? nested.internal);

  const fields = [
    ...(Array.isArray(observable.fields) ? observable.fields : []),
    ...(Array.isArray(nested.fields) ? nested.fields : []),
    field,
  ].filter(
    (candidate) =>
      typeof candidate === 'string' && candidate.trim() !== ''
  );

  if (type === 'hash') {
    value = value
      .replace(/^(?:MD5|SHA-?1|SHA-?256|SHA-?512)\s*=\s*/i, '')
      .replace(/\s+/g, '')
      .toLowerCase();
  } else if (type === 'ip') {
    value = value.toLowerCase();
  } else if (type === 'domain') {
    value = value.replace(/\.$/, '').toLowerCase();
  }

  const normalizedJson = {
    ...observable,
    type,
    value,
    field,
    internal,
    fields: [...new Set(fields.map((candidate) => candidate.trim()))],
  };

  if (!type || !value) {
    output.push({ ...item, json: normalizedJson });
    continue;
  }

  const key = `${type}:${value}`;

  if (!seen.has(key)) {
    const normalizedItem = { ...item, json: normalizedJson };
    seen.set(key, normalizedItem);
    output.push(normalizedItem);
    continue;
  }

  const existing = seen.get(key);

  existing.json.internal =
    isInternal(existing.json.internal) || internal;

  existing.json.fields = [
    ...new Set([
      ...(existing.json.fields ?? []),
      ...normalizedJson.fields,
    ]),
  ];
}

return output;

const INTERNAL_DOMAIN_SUFFIXES = [
  'lab',
  'local',
  'lan',
  'internal',
  'localdomain',
  'localhost',
  'test',
  'invalid',
  'home.arpa',
];

function parseIPv4(value) {
  const parts = String(value).split('.');

  if (
    parts.length !== 4 ||
    parts.some((part) => !/^\d{1,3}$/.test(part))
  ) {
    return null;
  }

  const numbers = parts.map(Number);

  if (numbers.some((part) => part < 0 || part > 255)) {
    return null;
  }

  return numbers;
}

function isNonPublicIPv4(parts) {
  const [a, b, c] = parts;

  return (
    a === 0 ||
    a === 10 ||
    a === 127 ||
    (a === 100 && b >= 64 && b <= 127) ||
    (a === 169 && b === 254) ||
    (a === 172 && b >= 16 && b <= 31) ||
    (a === 192 && b === 0 && c === 0) ||
    (a === 192 && b === 0 && c === 2) ||
    (a === 192 && b === 88 && c === 99) ||
    (a === 192 && b === 168) ||
    (a === 198 && (b === 18 || b === 19)) ||
    (a === 198 && b === 51 && c === 100) ||
    (a === 203 && b === 0 && c === 113) ||
    a >= 224
  );
}

function isNonPublicOrInvalidIPv6(value) {
  const address = String(value)
    .replace(/^\[|\]$/g, '')
    .split('%')[0]
    .toLowerCase();

  if (!address.includes(':')) return true;

  const doubleColonCount = (address.match(/::/g) ?? []).length;
  const groups = address.split(':').filter(Boolean);

  if (
    doubleColonCount > 1 ||
    address.includes('.') ||
    groups.some((group) => !/^[0-9a-f]{1,4}$/.test(group)) ||
    (doubleColonCount === 0 && groups.length !== 8) ||
    (doubleColonCount === 1 && groups.length >= 8)
  ) {
    return true;
  }

  const firstGroup = groups[0];
  if (!firstGroup) return true;

  const first = Number.parseInt(firstGroup, 16);

  // Allow only IPv6 global-unicast space (2000::/3).
  if (first < 0x2000 || first > 0x3fff) return true;

  // Documentation-only IPv6 range.
  if (/^2001:db8(?::|$)/.test(address)) return true;

  return false;
}

function hostSkipReason(rawHost) {
  let host = String(rawHost ?? '')
    .trim()
    .replace(/^\[|\]$/g, '');

  if (!host) return 'Missing URL host';

  if (host.includes(':')) {
    return isNonPublicOrInvalidIPv6(host)
      ? 'Non-public or invalid IPv6 host'
      : null;
  }

  if (/[\/?#@\s\\]/.test(host)) {
    return 'Invalid hostname';
  }

  host = host.replace(/\.$/, '').toLowerCase();

  const ipv4 = parseIPv4(host);

  if (ipv4) {
    return isNonPublicIPv4(ipv4) ? 'Non-public IPv4 host' : null;
  }

  if (/^[\d.]+$/.test(host)) {
    return 'Invalid or non-public IP host';
  }

  if (!host.includes('.')) {
    return 'Single-label or local hostname';
  }

  const labels = host.split('.');

  if (
    labels.some(
      (label) =>
        !label ||
        label.length > 63 ||
        !/^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$/.test(label),
    )
  ) {
    return 'Invalid hostname';
  }

  if (
    INTERNAL_DOMAIN_SUFFIXES.some(
      (suffix) => host === suffix || host.endsWith(`.${suffix}`),
    )
  ) {
    return 'Local or internal domain suffix';
  }

  return null;
}

function urlSkipReason(value) {
  const input = String(value ?? '').trim();

  if (!input || /[\s\\]/.test(input)) {
    return 'Invalid URL';
  }

  const schemeMatch = input.match(/^([a-z][a-z0-9+.-]*):\/\//i);

  if (!schemeMatch) {
    return 'Invalid URL';
  }

  const scheme = schemeMatch[1].toLowerCase();

  if (!['http', 'https'].includes(scheme)) {
    return 'Unsupported URL scheme';
  }

  const authority = input
    .slice(schemeMatch[0].length)
    .split(/[/?#]/, 1)[0];

  if (!authority) {
    return 'Missing URL host';
  }

  if (authority.includes('@')) {
    return 'URL contains credentials';
  }

  let host;

  function isValidPort(port) {
    return /^\d{1,5}$/.test(port) && Number(port) <= 65535;
  }

  if (authority.startsWith('[')) {
    const closingBracket = authority.indexOf(']');

    if (closingBracket < 0) {
      return 'Invalid URL';
    }

    host = authority.slice(1, closingBracket);
    const portSuffix = authority.slice(closingBracket + 1);

    if (
      portSuffix &&
      (!portSuffix.startsWith(':') ||
        !isValidPort(portSuffix.slice(1)))
    ) {
      return 'Invalid URL';
    }
  } else {
    const colonCount = (authority.match(/:/g) ?? []).length;

    if (colonCount > 1) {
      return 'Invalid URL';
    }

    const colonIndex = authority.lastIndexOf(':');

    if (colonIndex >= 0) {
      host = authority.slice(0, colonIndex);
      const port = authority.slice(colonIndex + 1);

      if (!isValidPort(port)) {
        return 'Invalid URL';
      }
    } else {
      host = authority;
    }
  }

  return hostSkipReason(host);
}

function ipSkipReason(value) {
  const candidate = String(value ?? '')
    .trim()
    .replace(/^\[|\]$/g, '');

  const ipv4 = parseIPv4(candidate);

  if (ipv4) {
    return isNonPublicIPv4(ipv4) ? 'Non-public IPv4 address' : null;
  }

  if (candidate.includes(':')) {
    return isNonPublicOrInvalidIPv6(candidate)
      ? 'Non-public or invalid IPv6 address'
      : null;
  }

  return 'Invalid IP address';
}

const observable = $json ?? {};
const type = String(observable.type ?? '').trim().toLowerCase();
const value = String(observable.value ?? '').trim();

let reason = null;

if (!type || !value) {
  reason = 'Missing observable type or value';
} else if (
  observable.internal === true ||
  String(observable.internal).toLowerCase() === 'true'
) {
  reason = 'Marked internal by normalization';
} else if (type === 'ip') {
  reason = ipSkipReason(value);
} else if (type === 'domain') {
  reason = hostSkipReason(value);
} else if (type === 'url') {
  reason = urlSkipReason(value);
} else if (type !== 'hash') {
  reason = 'Unsupported Cortex observable type';
}

return {
  json: {
    ...observable,
    type,
    value,
    cortex_eligible: reason === null,
    cortex_skip_reason: reason,
  },
};

/**
 * SOC - Error Formatter (Cortex services)
 * Stage: Failure handling (#72)
 *
 * One Code node per Cortex service, named "Error Formatter - <service>".
 * Input:  error outputs of "Execute <service>" and "Get a report <service>"
 * Output: one record per failed observable:
 *         { service, node, observable, error, timestamp }
 *
 * n8n Code node:
 * Mode: Run Once for All Items
 * Language: JavaScript
 *
 * Change only the five constants below:
 *
 * | Formatter  | SERVICE_NAME | EXECUTE_NODE       | REPORT_NODE                | SOURCE_NODES                                   | TYPES    |
 * |------------|--------------|--------------------|----------------------------|------------------------------------------------|----------|
 * | Maltiverse | Maltiverse   | Execute Maltiverse | Get a report Maltiverse    | Normalize Alert, Dedupe Cortex Observables     | domain   |
 * | AbuseIPDB  | AbuseIPDB    | Execute AbuseIPDB  | Get a report AbuseIPDB     | Filter Cortex-Eligible IPs                     | ip       |
 * | TeamCymru  | TeamCymru    | Execute TeamCymru  | Get a report TeamCymru     | Normalize Alert, Dedupe Cortex Observables     | hash     |
 * | CirclHash  | CirclHash    | Execute CirclHash  | Get a report CirclHash     | Normalize Alert, Dedupe Cortex Observables     | hash     |
 * | VirusTotal | VirusTotal   | Execute VirusTotal | Get a report UnshortenLink | Normalize Alert, Dedupe Cortex Observables     | url      |
 *
 * How the failed observable is found:
 * An error item contains only the error message, and n8n item linking is not
 * reliable here (the Cortex node does not keep item links for more than one
 * item, and the polling loop loses them). The observables are therefore found
 * by comparing values:
 * - error from Execute:      sent observables of TYPES minus those with a job
 * - error from Get a report: created jobs minus jobs that already finished or
 *                            are still in the current polling round
 */

const SERVICE_NAME = 'Maltiverse';
const EXECUTE_NODE = 'Execute Maltiverse';
const REPORT_NODE  = 'Get a report Maltiverse';
const SOURCE_NODES = ['Normalize Alert', 'Dedupe Cortex Observables'];
const TYPES        = ['domain'];

const safe  = fn => { try { return fn() ?? []; } catch { return []; } };
const jobId = j => j?.id ?? j?._id;

const collect = (o, out = [], d = 0) => {
  if (!o || typeof o !== 'object' || d > 6) return out;
  const type  = o.type ?? o.dataType;
  const value = o.value ?? o.data;
  if (typeof value === 'string' && TYPES.includes(type) && o.internal !== true) out.push(value);
  for (const v of Object.values(o)) collect(v, out, d + 1);
  return out;
};

const sent = [...new Set(SOURCE_NODES.flatMap(n => safe(() => $(n).all())).flatMap(x => collect(x.json)))];
const jobs = safe(() => $(EXECUTE_NODE).all(0)).map(x => x.json);
let failed;

if ($prevNode.name === EXECUTE_NODE) {
  const ok = new Set(jobs.map(j => j.data));
  failed = sent.filter(o => !ok.has(o));
} else {
  const run = $prevNode.runIndex ?? 0;
  const last = {};
  for (let r = 0; r < run; r++)
    safe(() => $(REPORT_NODE).all(0, r)).forEach(x => { last[jobId(x.json)] = x.json.status; });
  const now = new Set(safe(() => $(REPORT_NODE).all(0, run)).map(x => jobId(x.json)));
  failed = jobs
    .filter(j => !['Success', 'Failure'].includes(last[jobId(j)]) && !now.has(jobId(j)))
    .map(j => j.data);
}

return $input.all().map((input, i) => ({
  json: {
    service:    SERVICE_NAME,
    node:       $prevNode.name,
    observable: failed[i] ?? 'unknown',
    error:      input.json?.error?.message ?? input.json?.error ?? 'unknown',
    timestamp:  new Date().toISOString(),
  },
  pairedItem: { item: i },
}));

